 readonly DatabaseFixture db=new();public Task InitializeAsync()=>db.InitializeAsync();public Task DisposeAsync()=>db.DisposeAsync();Task<object?> S(string sql,params(string,object)[]args)=>db.OwnerScalarAsync(sql,args);static Guid Id(JsonElement e)=>e.GetProperty("id").GetGuid();static JsonElement Data(JsonElement e)=>e.GetProperty("data");
 async Task<DateOnly> Today()=>DateOnly.Parse((string)(await S("SELECT((now()AT TIME ZONE timezone)::date)::text FROM core.companies WHERE id=@c",("c",db.Company)))!);
 async Task<string> Range()=>"from="+(await Today()).ToString("yyyy-MM-dd")+"&to="+(await Today()).AddDays(1).ToString("yyyy-MM-dd");
 async Task<JsonElement> Read(HttpClient c,string kind,string extra="")=>await Get(c,"/workbench/"+kind+(extra.Length>0?"?"+extra:""));
 [Theory][InlineData("finance")][InlineData("sales")][InlineData("office")][InlineData("banks")][InlineData("warehouse")]
 public async Task Empty_dashboard_is_read_only_authenticated_and_does_not_create_audit_or_ledger_rows(string kind)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var before=await S("SELECT count(*)FROM platform.audit_events WHERE company_id=@c",("c",db.Company));var r=await Read(c,kind);Assert.True(r.GetProperty("readOnly").GetBoolean());Assert.Equal(db.Company,r.GetProperty("companyId").GetGuid());Assert.Equal("Australia/Sydney",r.GetProperty("timezone").GetString());Assert.Equal(before,await S("SELECT count(*)FROM platform.audit_events WHERE company_id=@c",("c",db.Company)));Assert.Equal(0L,await S("SELECT count(*)FROM accounting.journal_entries WHERE company_id=@c",("c",db.Company)));using var response=await c.GetAsync("/api/v1/workbench/"+kind);Assert.True(response.Headers.CacheControl!.NoStore);using var anonymous=api.CreateClient();Assert.Equal(HttpStatusCode.Unauthorized,(await anonymous.GetAsync("/api/v1/workbench/"+kind)).StatusCode);}
 [Theory][InlineData("SALES","finance")][InlineData("SALES","office")][InlineData("SALES","banks")][InlineData("WAREHOUSE","finance")][InlineData("WAREHOUSE","sales")][InlineData("FINANCE","office")][InlineData("PROCUREMENT","office")]
