 [Fact]public async Task Finance_dashboard_matches_canonical_reports_and_chart_totals()
 {await using var api=new TestApi(db);using var c=api.Authenticated();await Sale(c);var range=await Range();var w=Data(await Read(c,"finance",range));var p=await Get(c,"/accounting/reports/profit-and-loss?"+range);var b=await Get(c,"/accounting/reports/balance-sheet?asOf="+(await Today()).ToString("yyyy-MM-dd"));var a=await Get(c,"/accounting/reports/receivables-aging?asOf="+(await Today()).ToString("yyyy-MM-dd"));Assert.True(JsonElement.DeepEquals(p.GetProperty("totals"),w.GetProperty("profitLoss").GetProperty("totals")),"PNL "+p.GetRawText()+" vs "+w.GetRawText());Assert.True(JsonElement.DeepEquals(b.GetProperty("totals"),w.GetProperty("financialPosition").GetProperty("totals")),"BS "+b.GetRawText()+" vs "+w.GetRawText());Assert.True(JsonElement.DeepEquals(a.GetProperty("totals"),w.GetProperty("receivables").GetProperty("totals")),"AR "+a.GetRawText()+" vs "+w.GetRawText());var chart=w.GetProperty("incomeExpenseChart").EnumerateArray().ToArray();Assert.Equal(D(p.GetProperty("totals").GetProperty("revenue")),chart.Sum(x=>D(x.GetProperty("revenue"))));Assert.Equal(D(p.GetProperty("totals").GetProperty("expenses")),chart.Sum(x=>D(x.GetProperty("expenses"))));}
 async Task<(SalesData Sales,Guid Order,JsonElement Invoice)> Sale(HttpClient c)
 {await CompanyTaxSettings.ConfigureAsync(db.Owner,db.Company,true,"NON_CASH",DatabaseFixture.Issuer,db.Subject);var d=await Setup(db,c,0);var p=await Get(c,$"/products/{d.Product}");await Expect(await Send(c,HttpMethod.Put,$"/products/{d.Product}",new ProductMaintenance(p.GetProperty("sku").GetString()!,"Workbench service",p.GetProperty("taxCodeId").GetGuid(),ItemType:"SERVICE",WholePacks:false),1),HttpStatusCode.OK);var q=await Submitted(c,d.Draft(3)with{Lines=[new(d.BoxUnit,Quantity:3,UnitPrice:100)]});var order=(await Expect(await Approve(c,q.Id,q.Version),HttpStatusCode.Created)).GetProperty("orderId").GetGuid();var line=Id((await Get(c,$"/sales-orders/{order}")).GetProperty("lines")[0]);var invoice=await Expect(await Send(c,HttpMethod.Post,$"/sales-orders/{order}/invoices",new InvoiceInput([new(line,3)],"Completed"),1),HttpStatusCode.Created);return(d,order,invoice);}
 [Fact]public async Task Assigned_sales_scope_filters_counts_documents_trends_and_unified_customer_access()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await Sale(c);var y=await Sale(c);var sales=await Staff(db,"SALES",x.Sales);using var user=api.Authenticated(sales.Subject);var r=Data(await Read(user,"sales",await Range()));Assert.Equal(1,r.GetProperty("customerCount").GetInt32());Assert.Single(r.GetProperty("customers").GetProperty("items").EnumerateArray());Assert.Equal(1,r.GetProperty("documents").GetProperty("orders").GetProperty("data").GetProperty("totalCount").GetInt32());Assert.Equal(300,D(r.GetProperty("sales").GetProperty("data").GetProperty("totals").GetProperty("net")));await Expect(await user.GetAsync($"/api/v1/workbench/customers/{y.Sales.Customer}"),HttpStatusCode.NotFound);var detail=Data(await Read(user,$"customers/{x.Sales.Customer}",await Range()));Assert.Equal("FORBIDDEN",detail.GetProperty("receivables").GetProperty("status").GetString());Assert.DoesNotContain("credit_limit",detail.GetRawText());await S("DELETE FROM identity.customer_assignments WHERE company_id=@c AND membership_id=@m",("c",db.Company),("m",sales.Membership));Assert.Equal(0,Data(await Read(user,"sales")).GetProperty("customerCount").GetInt32());await Expect(await user.GetAsync($"/api/v1/workbench/customers/{x.Sales.Customer}"),HttpStatusCode.NotFound);}
 [Fact]public async Task Office_customer_view_keeps_another_authors_private_note_hidden()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Setup(db,c,0);var sales=await Staff(db,"SALES",d);using var author=api.Authenticated(sales.Subject);var secret=Guid.NewGuid().ToString();await Expect(await Send(author,HttpMethod.Post,"/crm/collaboration",new CollaborationCreate(Guid.NewGuid(),"NOTE",d.Customer,null,JsonSerializer.SerializeToElement(new CustomerNote(secret,"PRIVATE"),ApiJson.Options))),HttpStatusCode.Created);await Expect(await Send(author,HttpMethod.Post,"/crm/collaboration",new CollaborationCreate(Guid.NewGuid(),"NOTE",d.Customer,null,JsonSerializer.SerializeToElement(new CustomerNote("Team note","TEAM"),ApiJson.Options))),HttpStatusCode.Created);var r=Data(await Read(c,$"customers/{d.Customer}"));Assert.Equal(1,r.GetProperty("collaboration").GetProperty("data").GetProperty("notes").GetInt32());Assert.DoesNotContain(secret,r.GetRawText());var own=Data(await Read(author,$"customers/{d.Customer}"));Assert.Equal(2,own.GetProperty("collaboration").GetProperty("data").GetProperty("notes").GetInt32());}
 [Fact]public async Task Submitted_quote_attention_uses_quote_business_status()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Setup(db,c,0);await Submitted(c,d.Draft());var r=Data(await Read(c,"office"));Assert.Equal(1,r.GetProperty("documents").GetProperty("quotes").GetProperty("data").GetProperty("submitted").GetInt32());}
 [Fact]public async Task Warehouse_view_is_scoped_and_never_discloses_money()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Setup(db,c);var other=await Setup(db,c);var staff=await Staff(db,"WAREHOUSE",d);using var user=api.Authenticated(staff.Subject);var r=Data(await Read(user,"warehouse"));Assert.Equal(1,r.GetProperty("totalCount").GetInt32());Assert.Equal(d.Warehouse,Id(r.GetProperty("items")[0]));Assert.DoesNotContain("cost",r.GetProperty("items").GetRawText(),StringComparison.OrdinalIgnoreCase);Assert.DoesNotContain("price",r.GetRawText(),StringComparison.OrdinalIgnoreCase);await Expect(await user.GetAsync($"/api/v1/workbench/warehouse?warehouseId={other.Warehouse}"),HttpStatusCode.NotFound);}
 [Fact]public async Task Bank_hub_balances_match_directory_but_do_not_claim_live_feeds()
 {await using var api=new TestApi(db);using var c=api.Authenticated();await Sale(c);var r=Data(await Read(c,"banks"));Assert.False(r.GetProperty("feeds").GetProperty("liveConnection").GetBoolean());var rows=(await Get(c,"/bank-accounts")).GetProperty("items");foreach(var bank in r.GetProperty("items").EnumerateArray()){var old=rows.EnumerateArray().Single(x=>Id(x)==Id(bank));Assert.Equal(D(old.GetProperty("signedBalance")),D(bank.GetProperty("bookBalance")));Assert.False(bank.TryGetProperty("accountNumber",out _));}}
 [Fact]public async Task Unauthorized_modules_are_explicitly_unavailable_instead_of_zero_or_leaking_data()
 {await using var api=new TestApi(db);using var c=api.Authenticated();await S("DELETE FROM identity.role_permissions WHERE company_id=@c AND permission_code IN('reports.sales.read','crm.tasks.read','crm.collaboration.read','incentives.self.read')",("c",db.Company));var r=Data(await Read(c,"sales"));foreach(var key in new[]{"sales","tasks","collaboration","incentives"}){Assert.Equal("FORBIDDEN",r.GetProperty(key).GetProperty("status").GetString());Assert.Equal(JsonValueKind.Null,r.GetProperty(key).GetProperty("data").ValueKind);}}
