 [Fact]public async Task Pending_up_next_excludes_completed_tasks_and_unrelated_staff_tasks()
 {await using var api=new TestApi(db);var finance=await Staff(db,"FINANCE");using var c=api.Authenticated(finance.Subject);var staff=await Staff(db,"SALES");var user=(Guid)(await S("SELECT user_id FROM identity.memberships WHERE company_id=@c AND id=@m",("c",db.Company),("m",staff.Membership)))!;using var sales=api.Authenticated(staff.Subject);var done=await Expect(await Send(c,HttpMethod.Post,"/crm/tasks",new TaskCreate(Guid.NewGuid(),new TaskDetails("Finished",db.Actor,DueAt:DateTimeOffset.UtcNow.AddHours(-2)))),HttpStatusCode.Created);await Expect(await Send(c,HttpMethod.Post,$"/crm/tasks/{Id(done)}/complete",version:1),HttpStatusCode.OK);await Expect(await Send(c,HttpMethod.Post,"/crm/tasks",new TaskCreate(Guid.NewGuid(),new TaskDetails("Pending",db.Actor,DueAt:DateTimeOffset.UtcNow.AddHours(1)))),HttpStatusCode.Created);await Expect(await Send(sales,HttpMethod.Post,"/crm/tasks",new TaskCreate(Guid.NewGuid(),new TaskDetails("Other personal task",user))),HttpStatusCode.Created);var panel=Data(await Read(c,"finance")).GetProperty("tasks").GetProperty("data");Assert.Equal(1,panel.GetProperty("open").GetInt32());Assert.Single(panel.GetProperty("upNext").EnumerateArray());Assert.Equal("Pending",panel.GetProperty("upNext")[0].GetProperty("title").GetString());}
 [Fact]public async Task Sales_rows_page_without_changing_totals_or_exposing_source_facts()
 {await using var api=new TestApi(db);using var c=api.Authenticated();await Sale(c);await Sale(c);var a=Data(await Read(c,"sales",await Range()+"&pageSize=1")).GetProperty("sales").GetProperty("data");var b=Data(await Read(c,"sales",await Range()+"&pageSize=1&page=2")).GetProperty("sales").GetProperty("data");Assert.Equal(600,D(a.GetProperty("totals").GetProperty("net")));Assert.Equal(600,D(b.GetProperty("totals").GetProperty("net")));Assert.Equal(2,a.GetProperty("rowCount").GetInt32());Assert.Single(a.GetProperty("rows").EnumerateArray());Assert.NotEqual(a.GetProperty("rows")[0].GetRawText(),b.GetProperty("rows")[0].GetRawText());Assert.False(a.TryGetProperty("sourceFacts",out _));}
 [Theory][InlineData("finance")][InlineData("sales")][InlineData("office")]
 public async Task Concurrent_dashboard_reloads_never_create_business_or_outbox_writes(string kind)
 {await using var api=new TestApi(db);using var c=api.Authenticated();await Sale(c);var before=await S("SELECT count(*)FROM platform.outbox_events WHERE company_id=@c",("c",db.Company));var ledger=await S("SELECT count(*)FROM accounting.journal_entries WHERE company_id=@c",("c",db.Company));var all=await Task.WhenAll(Enumerable.Range(0,5).Select(_=>Read(c,kind)));Assert.All(all,x=>Assert.True(x.GetProperty("readOnly").GetBoolean()));Assert.Equal(before,await S("SELECT count(*)FROM platform.outbox_events WHERE company_id=@c",("c",db.Company)));Assert.Equal(ledger,await S("SELECT count(*)FROM accounting.journal_entries WHERE company_id=@c",("c",db.Company)));}
 [Fact]public async Task Dashboard_historical_cutoff_does_not_relabel_current_tasks_as_historical()
 {await using var api=new TestApi(db);using var c=api.Authenticated();await Sale(c);var today=await Today();var w=await Read(c,"finance",$"from={today.AddDays(-1):yyyy-MM-dd}&to={today:yyyy-MM-dd}");Assert.Equal(0,D(Data(w).GetProperty("profitLoss").GetProperty("totals").GetProperty("revenue")));Assert.Equal("CURRENT_COMMITTED_AND_CURRENT_AUTHORIZATION",w.GetProperty("operationalBasis").GetString());Assert.Equal("CURRENT_AUTHORIZED_TASKS",Data(w).GetProperty("tasks").GetProperty("data").GetProperty("basis").GetString());}
 [Fact]public async Task Bank_hub_counts_partially_matched_lines_until_the_remainder_is_matched()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var bank=await Create(c,"/bank-accounts",new Htt.Host.Api.Accounting.BankAccountInput(Code(),"C09 bank","BANK","062000","12345678","HTT test"));var supplier=await Create(c,"/suppliers",new SupplierMaintenance(Code(),"Supplier",null));await Expect(await Send(c,HttpMethod.Post,$"/suppliers/{supplier}/payments",new Htt.Host.Api.Purchasing.SupplierPaymentInput(10,"BANK_TRANSFER",Code(),10,Notes:"Advance",BankAccountId:bank)),HttpStatusCode.Created);var cash=(await Get(c,$"/bank-accounts/{bank}/cash-clearing")).GetProperty("items")[0].GetProperty("id").GetGuid();var today=await Today();var statement=await Expect(await Send(c,HttpMethod.Post,$"/bank-accounts/{bank}/statements/import",new Htt.Host.Api.Accounting.BankStatementImportInput(Code(),today,today,0,-20,[new(today,-20,"Statement","Ref",Code())])),HttpStatusCode.Created);var line=statement.GetProperty("lines")[0].GetProperty("id").GetGuid();await Expect(await Send(c,HttpMethod.Post,$"/bank-statement-lines/{line}/matches",new Htt.Host.Api.Accounting.BankMatchInput(Code(),"Partial",[new(cash,10)]),1),HttpStatusCode.Created);var hub=Data(await Read(c,"banks"));var entry=hub.GetProperty("items").EnumerateArray().Single(x=>Id(x)==bank);Assert.Equal(1,entry.GetProperty("unmatchedLines").GetInt32());Assert.Equal(-10,D(entry.GetProperty("bookBalance")));}
