 {await using var api=new TestApi(db);using var c=api.Authenticated();var tomorrow=(await Today()).AddDays(1);await Expect(await c.GetAsync($"/api/v1/workbench/banks?asOf={tomorrow:yyyy-MM-dd}"),HttpStatusCode.UnprocessableEntity);await Expect(await c.GetAsync($"/api/v1/workbench/finance?to={tomorrow.AddDays(1):yyyy-MM-dd}"),HttpStatusCode.UnprocessableEntity);}
 [Fact]public async Task Gateway_cannot_be_called_without_its_permission_even_using_raw_app_SQL()
 {var staff=await Staff(db,"SALES");var user=(Guid)(await S("SELECT user_id FROM identity.memberships WHERE company_id=@c AND id=@m",("c",db.Company),("m",staff.Membership)))!;await using var source=NpgsqlDataSource.Create(db.App);await using var session=new CompanySession(source);await session.BeginAsync(db.Company,user,"c09-denied",default);var e=await Assert.ThrowsAsync<PostgresException>(()=>Sql.RowsAsync(session,"SELECT workbench.query('FINANCE','{}')",default));Assert.Equal("42501",e.SqlState);}
 [Fact]public async Task A_single_workbench_statement_keeps_one_snapshot_when_credit_commits_mid_query()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await Sale(c);await using var credit=await db.SessionAsync();await Sql.RowsAsync(credit,"SELECT sales.post_amount_credit_note(@id,'C09 concurrent',@items::jsonb)",default,("id",Id(x.Invoice)),("items",JsonSerializer.Serialize(new[]{new{invoiceLineId=Id(x.Invoice.GetProperty("lines")[0]),net=25,tax=2.5m,description="Concurrent"}})));await using var gate=new NpgsqlConnection(db.Owner);await gate.OpenAsync();long key=Random.Shared.NextInt64(1,long.MaxValue);await using(var take=new NpgsqlCommand("SELECT pg_advisory_lock(@key)",gate)){take.Parameters.AddWithValue("key",key);await take.ExecuteNonQueryAsync();}await using var reader=await db.SessionAsync();var query=Sql.RowsAsync(reader,"WITH gate AS MATERIALIZED(SELECT pg_advisory_xact_lock(@key))SELECT workbench.query('FINANCE',@filter::jsonb)::text AS body FROM gate",default,("key",key),("filter",JsonSerializer.Serialize(new{from=(await Today()).ToString("yyyy-MM-dd"),to=(await Today()).AddDays(1).ToString("yyyy-MM-dd")})));bool waiting=false;for(int i=0;i<100;i++){waiting=(bool)(await S("SELECT cardinality(pg_blocking_pids(@pid))>0",("pid",reader.Connection.ProcessID)))!;if(waiting)break;await Task.Delay(10);}Assert.True(waiting,"Reader did not reach the snapshot barrier");await credit.Transaction.CommitAsync();await using(var release=new NpgsqlCommand("SELECT pg_advisory_unlock(@key)",gate)){release.Parameters.AddWithValue("key",key);await release.ExecuteNonQueryAsync();}var rows=await query;var old=Data(JsonDocument.Parse((string)rows[0]["body"]!).RootElement);Assert.Equal(300,D(old.GetProperty("profitLoss").GetProperty("totals").GetProperty("revenue")));Assert.Equal(330,D(old.GetProperty("receivables").GetProperty("totals").GetProperty("netBalance")));Assert.Equal(275,D(Data(await Read(c,"finance",await Range())).GetProperty("profitLoss").GetProperty("totals").GetProperty("revenue")));}

 [Fact]public async Task Unified_customer_rebates_recheck_explicit_grants_and_do_not_include_own_commission()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Setup(db,c,0);var staff=await Staff(db,"SALES",d);var user=(Guid)(await S("SELECT user_id FROM identity.memberships WHERE company_id=@c AND id=@m",("c",db.Company),("m",staff.Membership)))!;using var sales=api.Authenticated(staff.Subject);var rebate=await Create(c,"/incentives/programs",new IncentiveProgramInput("REBATE","Customer rebate",d.Customer));var commission=await Create(c,"/incentives/programs",new IncentiveProgramInput("COMMISSION","Own commission",UserId:user));Assert.Single(Data(await Read(sales,"sales")).GetProperty("incentives").GetProperty("data").EnumerateArray());Assert.Empty(Data(await Read(sales,$"customers/{d.Customer}")).GetProperty("rebates").GetProperty("data").EnumerateArray());await Expect(await Send(c,HttpMethod.Put,$"/incentives/programs/{rebate}/display-grants",new IncentiveGrantInput(user,true),0),HttpStatusCode.OK);var body=Data(await Read(sales,$"customers/{d.Customer}"));var values=body.GetProperty("rebates").GetProperty("data");Assert.Single(values.EnumerateArray());Assert.Equal(rebate,values[0].GetProperty("programId").GetGuid());Assert.DoesNotContain(commission.ToString(),values.GetRawText());await Expect(await Send(c,HttpMethod.Put,$"/incentives/programs/{rebate}/display-grants",new IncentiveGrantInput(user,false),1),HttpStatusCode.OK);Assert.Empty(Data(await Read(sales,$"customers/{d.Customer}")).GetProperty("rebates").GetProperty("data").EnumerateArray());}
 [Fact]public async Task Approved_new_customer_keeps_origin_draft_in_the_unified_view()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var staff=await Staff(db,"SALES");using var sales=api.Authenticated(staff.Subject);var draft=await Create(sales,"/crm/drafts",new CrmDraftInput(Guid.NewGuid(),"CUSTOMER",null,new CrmDraftData("Workbench new customer",Code())));await Expect(await Send(sales,HttpMethod.Post,$"/crm/drafts/{draft}/submit",version:1),HttpStatusCode.OK);var accepted=await Expect(await Send(c,HttpMethod.Post,$"/crm/drafts/{draft}/review",new CrmReview(true,"Verified"),2),HttpStatusCode.OK);var customer=accepted.GetProperty("formalId").GetGuid();var body=Data(await Read(c,$"customers/{customer}"));Assert.Equal(customer,Id(body.GetProperty("customer")));Assert.Single(body.GetProperty("drafts").GetProperty("data").GetProperty("items").EnumerateArray());}

